svg.script:
'use strict';
/* ============ basic utils ============ */
const NS = 'http://www.w3.org/2000/svg';
const $ = (id) => document.getElementById(id);
const ROOT = document.documentElement;
function el(tag, attrs, parent) {
  const e = document.createElementNS(NS, tag);
  if (attrs) for (const k in attrs) e.setAttribute(k, attrs[k]);
  if (parent) parent.appendChild(e);
  return e;
}
function setA(e, attrs) { for (const k in attrs) e.setAttribute(k, attrs[k]); }
function text(parent, x, y, str, size, attrs) {
  const t = el('text', Object.assign({ x, y, 'font-size': size }, attrs || {}), parent);
  t.textContent = str;
  return t;
}
function show(e, on) { if (on) e.classList.remove('hidden'); else e.classList.add('hidden'); }
const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
const lerp = (a, b, t) => a + (b - a) * t;
const ease = (t) => 1 - Math.pow(1 - clamp(t, 0, 1), 3);
const TAU = Math.PI * 2;
function mulberry(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
let deco = mulberry(20260924);
const R2 = (a, b) => a + deco() * (b - a);
function hex2rgb(h) { const n = parseInt(h.slice(1), 16); return [n >> 16, (n >> 8) & 255, n & 255]; }
function rgb2hex(r, g, b) { return '#' + ((1 << 24) | (Math.round(r) << 16) | (Math.round(g) << 8) | Math.round(b)).toString(16).slice(1); }
function mix(a, b, t) { const x = hex2rgb(a), y = hex2rgb(b); return rgb2hex(lerp(x[0], y[0], t), lerp(x[1], y[1], t), lerp(x[2], y[2], t)); }
function shade(h, f) { return f < 0 ? mix(h, '#1a2233', -f) : mix(h, '#ffffff', f); }
const f1 = (v) => Math.round(v * 10) / 10;
/* wobbly circle / rounded rect with watercolor edges */

function wobbleCircle(cx, cy, r, amp, n, seed) {
  const rn = mulberry(seed), pts = [], ph = [rn() * TAU, rn() * TAU, rn() * TAU];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * TAU;
    const rr = r + amp * (Math.sin(a * 3 + ph[0]) * 0.5 + Math.sin(a * 5 + ph[1]) * 0.3 + Math.sin(a * 7 + ph[2]) * 0.2);
    pts.push([cx + Math.cos(a) * rr, cy + Math.sin(a) * rr]);
  }
  return smoothClosed(pts);
}
function smoothClosed(pts) {
  const n = pts.length; let d = '';
  for (let i = 0; i < n; i++) {
    const p0 = pts[(i - 1 + n) % n], p1 = pts[i], p2 = pts[(i + 1) % n], p3 = pts[(i + 2) % n];
    if (i === 0) d += 'M' + f1(p1[0]) + ' ' + f1(p1[1]);
    const c1x = p1[0] + (p2[0] - p0[0]) / 6, c1y = p1[1] + (p2[1] - p0[1]) / 6;
    const c2x = p2[0] - (p3[0] - p1[0]) / 6, c2y = p2[1] - (p3[1] - p1[1]) / 6;
    d += 'C' + f1(c1x) + ' ' + f1(c1y) + ' ' + f1(c2x) + ' ' + f1(c2y) + ' ' + f1(p2[0]) + ' ' + f1(p2[1]);
  }
  return d + 'Z';
}
function wobbleRect(x, y, w, h, rad, amp, seed) {
  const rn = mulberry(seed), pts = [];
  const per = 2 * (w + h), step = 26;
  const corner = (cx, cy, a0) => { for (let k = 0; k <= 4; k++) { const a = a0 + (k / 4) * (Math.PI / 2); pts.push([cx + Math.cos(a) * rad, cy + Math.sin(a) * rad]); } };
  const edge = (x0, y0, x1, y1) => {
    const len = Math.hypot(x1 - x0, y1 - y0), n = Math.max(1, Math.floor(len / step));
    for (let k = 1; k < n; k++) { const t = k / n; const j = (rn() - 0.5) * amp * 2; const nx = -(y1 - y0) / len, ny = (x1 - x0) / len; pts.push([lerp(x0, x1, t) + nx * j, lerp(y0, y1, t) + ny * j]); }
  };
  corner(x + w - rad, y + rad, -Math.PI / 2); edge(x + w, y + rad, x + w, y + h - rad);
  corner(x + w - rad, y + h - rad, 0); edge(x + w - rad, y + h, x + rad, y + h);
  corner(x + rad, y + h - rad, Math.PI / 2); edge(x, y + h - rad, x, y + rad);
  corner(x + rad, y + rad, Math.PI); edge(x + rad, y, x + w - rad, y);
  void per;
  return smoothClosed(pts);
}
function circlePath(cx, cy, r) { return 'M' + (cx + r) + ' ' + cy + 'a' + r + ' ' + r + ' 0 1 1 ' + (-2 * r) + ' 0a' + r + ' ' + r + ' 0 1 1 ' + (2 * r) + ' 0Z'; }

/* ============ constants ============ */
const W = 1280, H = 720;
const R = 20, D = 40, ROWH = R * Math.sqrt(3), COLS = 13;
const FL = 380, FR = 900, CEIL0 = 22, DEAD_Y = 604, MAX_ROWS = 19;
const LX = 640, LY = 640, SPEED = 1180, COLL = 33;
const AIM_MAX = 1.43;
const COLORS = [
  { name: '\u5c0f\u4e11\u9c7c', cn: '\u6a59', base: '#f28a3a' },
  { name: '\u6d77\u9f9f', cn: '\u7eff', base: '#4db36e' },
  { name: '\u6d77\u9a6c', cn: '\u84dd', base: '#3d82d4' },
  { name: '\u6c34\u6bcd', cn: '\u7d2b', base: '#9a67d2' },
  { name: '\u6d77\u661f', cn: '\u9ec4', base: '#efc23a' },
  { name: '\u7ae0\u9c7c', cn: '\u7ea2', base: '#e04e66' },
];
const DIFFS = [
  { name: '\u7b80\u5355', colors: 4, drop: 9, endDrop: 8, endMin: 5, desc: '4 \u79cd\u989c\u8272 \u00b7 \u4e0b\u964d\u6162' },
  { name: '\u666e\u901a', colors: 5, drop: 7, endDrop: 6, endMin: 4, desc: '5 \u79cd\u989c\u8272 \u00b7 \u6807\u51c6\u8282\u594f' },
  { name: '\u56f0\u96be', colors: 6, drop: 5, endDrop: 5, endMin: 3, desc: '6 \u79cd\u989c\u8272 \u00b7 \u4e0b\u964d\u5feb' },
];

/* sea creature silhouettes: f=ink fill, l=light fill, s=ink stroke, w=light stroke */
const CREATURES = [
  [ // clownfish
    ['f', 'M-9 0C-8-5.5-2-7.5 3-7C7.5-6.5 11-3.5 11.5 0C11 3.5 7.5 6.5 3 7C-2 7.5-8 5.5-9 0Z'],
    ['f', 'M-8 0L-13.5-5.5Q-12 0-13.5 5.5Z'], ['f', 'M-4-6.2Q0-11.5 5-6.6Z'], ['f', 'M-1 6.8Q1.5 10.5 4 6.5Z'],
    ['l', 'M1.8-6.9C3.2-3 3.2 3 1.8 6.9L-0.8 7.1C0.6 3 0.6-3-0.8-7.1Z'],
    ['l', 'M7.4-5.2C8.4-2 8.4 2 7.4 5.2L5.8 6C6.8 2 6.8-2 5.8-6Z'],
    ['l', circlePath(9.3, -1.6, 1.1)],
  ],
  [ // turtle
    ['f', 'M0-7.5C5.5-7.5 8.5-3.5 8.5 1C8.5 5.8 5 8.8 0 8.8C-5 8.8-8.5 5.8-8.5 1C-8.5-3.5-5.5-7.5 0-7.5Z'],
    ['f', 'M0-13C2.2-13 3.2-11.4 3-9.8C2.8-8.3 1.6-7.4 0-7.4C-1.6-7.4-2.8-8.3-3-9.8C-3.2-11.4-2.2-13 0-13Z'],
    ['f', 'M-6.5-4C-10.5-7.5-13.5-5.5-14-2.5C-11.5-2.8-9.2-2-7.6-0.6Z'], ['f', 'M6.5-4C10.5-7.5 13.5-5.5 14-2.5C11.5-2.8 9.2-2 7.6-0.6Z'],
    ['f', 'M-6 5.5C-9 6.5-10.5 9-10 11C-8 10.2-6.4 9.2-4.8 7.8Z'], ['f', 'M6 5.5C9 6.5 10.5 9 10 11C8 10.2 6.4 9.2 4.8 7.8Z'],
    ['f', 'M-1.2 8.6L0 11.5L1.2 8.6Z'],
    ['w', 'M-3-2.5L3-2.5L4.6 1.5L0 4.8L-4.6 1.5ZM-3-2.5L-5-6M3-2.5L5-6M4.6 1.5L8.3 2M-4.6 1.5L-8.3 2M0 4.8L0 8.6', 1],
  ],
  [ // seahorse
    ['f', 'M-2-10.5C0-12.6 3.4-11.8 4-9.2L10.6-8.4L10.6-6.3L4.3-6C6.8-3.4 7.4 1 5.2 3.8C3.8 5.6 2 6.2 1 7.6L-1.2 7.2C-1.4 4.4-3 2.4-3.8-0.4C-4.6-3.2-4.4-6.6-3.4-8.6C-3-9.4-2.6-10-2-10.5Z'],
    ['s', 'M0 7C-1.2 10.2 0.4 13 3 12.6C5 12.2 5.2 9.6 3.2 9.4', 2.6],
    ['f', 'M-3.9-1.5C-7.4-2.6-7.6 2-4.2 2.6Z'], ['f', 'M-1.8-10.6L-1.4-13.4L0.4-11.5Z'],
    ['l', circlePath(1.9, -8.7, 1.05)],
    ['w', 'M4.8-3.8L6.4-3.3M5.5-1.2L7.1-0.9M5.2 1.4L6.8 1.8', 0.8],
  ],
  [ // jellyfish
    ['f', 'M-9-1C-9.4-8.6-4.6-11.6 0-11.6C4.6-11.6 9.4-8.6 9-1C7.2-2.4 5.4-0.2 3.6-1.6C1.8-0.2 0-2.4-1.8-0.8C-3.6-2.4-5.4-0.2-6.8-1.6C-7.6-0.8-8.4-0.8-9-1Z'],
    ['s', 'M-5.6-0.6C-7.6 3-3.8 6-5.8 10.6M-1.8 0C-3.4 4.2 0.6 7-1.2 12M2 0C0.4 4 4.2 7 2.2 11.4M5.8-0.8C4.2 2.8 8 5.6 6.2 9.8', 1.6],
    ['l', circlePath(-5.1, -6.8, 1.3) + circlePath(0.6, -8, 1) + circlePath(4.2, -5, 1.2)],
  ],
  null, // starfish (generated below)
  [ // octopus
    ['f', 'M0-12C6.2-12 8.4-7 8.2-3.4C8-0.6 6.6 1.6 5.2 2.8L-5.2 2.8C-6.6 1.6-8-0.6-8.2-3.4C-8.4-7-6.2-12 0-12Z'],
    ['s', 'M-5 2.2C-9.4 4.6-10.4 9-7 10.8M-2 2.8C-4.2 6.6-3.8 10-1.2 11.2M2 2.8C4.2 6.6 3.8 10 1.2 11.2M5 2.2C9.4 4.6 10.4 9 7 10.8', 2.6],
    ['l', circlePath(-3.3, -4.6, 1.9) + circlePath(3.3, -4.6, 1.9)],
    ['f', circlePath(-3.1, -4.3, 0.8) + circlePath(3.5, -4.3, 0.8)],
  ],
];
(function makeStar() {
  let d = '';
  const ro = 12.2, ri = 5, k = 0.72;
  for (let i = 0; i < 5; i++) {
    const a = -Math.PI / 2 + (i * TAU) / 5, am = a - Math.PI / 5, ap = a + Math.PI / 5;
    const q0 = [Math.cos(am) * ri, Math.sin(am) * ri], tip = [Math.cos(a) * ro, Math.sin(a) * ro], q1 = [Math.cos(ap) * ri, Math.sin(ap) * ri];
    const pa = [lerp(q0[0], tip[0], k), lerp(q0[1], tip[1], k)], pb = [lerp(q1[0], tip[0], k), lerp(q1[1], tip[1], k)];
    d += (i === 0 ? 'M' : 'L') + f1(q0[0]) + ' ' + f1(q0[1]) + 'L' + f1(pa[0]) + ' ' + f1(pa[1]) + 'Q' + f1(tip[0] * 1.08) + ' ' + f1(tip[1] * 1.08) + ' ' + f1(pb[0]) + ' ' + f1(pb[1]);
  }
  let dots = circlePath(0, 0, 1.3);
  for (let i = 0; i < 5; i++) { const a = -Math.PI / 2 + (i * TAU) / 5; dots += circlePath(Math.cos(a) * 6.4, Math.sin(a) * 6.4, 0.95); }
  CREATURES[4] = [['f', d + 'Z'], ['l', dots]];
})();
const FISH_D = 'M-8 0C-5-5.4 3.5-6 9 0C3.5 6-5 5.4-8 0Z M-7 0L-12.5-5L-11.4 0L-12.5 5Z';
const BOLT_D = 'M3.2-12.5L-6.2 1.4L-0.6 1.4L-3.2 12.5L6.4-2.2L0.8-2.2L4-12.5Z';
const SPARK_D = 'M0-10C1.2-2.4 2.4-1.2 10 0C2.4 1.2 1.2 2.4 0 10C-1.2 2.4-2.4 1.2-10 0C-2.4-1.2-1.2-2.4 0-10Z';
/* ============ audio: realtime Web Audio synthesis ============ */
const midi = (n) => 440 * Math.pow(2, (n - 69) / 12);
const AU = {
  ctx: null, master: null, sfxG: null, musG: null, rev: null, muted: false, duck: 1,
  nextT: 0, step: 0, timer: 0, melRng: mulberry(77),
  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      const c = this.ctx = new AC();
      this.master = c.createGain(); this.master.gain.value = this.muted ? 0 : 0.9;
      const comp = c.createDynamicsCompressor(); comp.threshold.value = -14; comp.ratio.value = 4;
      this.master.connect(comp); comp.connect(c.destination);
      this.sfxG = c.createGain(); this.sfxG.gain.value = 0.85; this.sfxG.connect(this.master);
      const lp = c.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 2400; lp.Q.value = 0.3;
      this.musG = c.createGain(); this.musG.gain.value = 0.3; this.musG.connect(lp); lp.connect(this.master);
      this.rev = c.createConvolver(); this.rev.buffer = this.impulse(2.8, 2.4);
      const rg = c.createGain(); rg.gain.value = 0.42; this.rev.connect(rg); rg.connect(this.master);
      this.nextT = c.currentTime + 0.15;
      this.timer = setInterval(() => this.schedule(), 50);
      if (c.state === 'suspended') c.resume();
    } catch (e) { this.ctx = null; }
  },
  impulse(sec, decay) {
    const c = this.ctx, len = Math.floor(c.sampleRate * sec), b = c.createBuffer(2, len, c.sampleRate);
    for (let ch = 0; ch < 2; ch++) { const d = b.getChannelData(ch); for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, decay); }
    return b;
  },
  noiseBuf() {
    if (!this._nb) { const c = this.ctx, n = c.sampleRate, b = c.createBuffer(1, n, n), d = b.getChannelData(0); for (let i = 0; i < n; i++) d[i] = Math.random() * 2 - 1; this._nb = b; }
    return this._nb;
  },
  setMute(m) { this.muted = m; if (this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.9, this.ctx.currentTime, 0.03); },
  setDuck(v) { this.duck = v; if (this.ctx) this.musG.gain.setTargetAtTime(0.3 * v, this.ctx.currentTime, 0.2); },
  env(g, t0, a, d, v) { g.gain.setValueAtTime(0.0001, t0); g.gain.exponentialRampToValueAtTime(v, t0 + a); g.gain.exponentialRampToValueAtTime(0.0001, t0 + d); },
  tone(o) {
    const c = this.ctx; if (!c || (this.muted && !o.music)) return;
    const t0 = o.at || c.currentTime + (o.t || 0);
    const osc = c.createOscillator(); osc.type = o.type || 'sine';
    osc.frequency.setValueAtTime(o.f, t0);
    if (o.f2) osc.frequency.exponentialRampToValueAtTime(o.f2, t0 + (o.sd || o.d));
    if (o.det) osc.detune.value = o.det;
    const g = c.createGain(); this.env(g, t0, o.a || 0.005, o.d, o.v || 0.2);
    osc.connect(g); g.connect(o.dest || this.sfxG);
    if (o.rev) { const s = c.createGain(); s.gain.value = o.rev; g.connect(s); s.connect(this.rev); }
    osc.start(t0); osc.stop(t0 + o.d + 0.05);
  },
  noise(o) {
    const c = this.ctx; if (!c || this.muted) return;
    const t0 = c.currentTime + (o.t || 0);
    const src = c.createBufferSource(); src.buffer = this.noiseBuf();
    const fl = c.createBiquadFilter(); fl.type = o.ft || 'bandpass'; fl.Q.value = o.q || 1;
    fl.frequency.setValueAtTime(o.f || 1000, t0); if (o.f2) fl.frequency.exponentialRampToValueAtTime(o.f2, t0 + o.d);
    const g = c.createGain(); this.env(g, t0, o.a || 0.004, o.d, o.v || 0.1);
    src.connect(fl); fl.connect(g); g.connect(this.sfxG);
    if (o.rev) { const s = c.createGain(); s.gain.value = o.rev; g.connect(s); s.connect(this.rev); }
    src.start(t0, Math.random() * 0.5); src.stop(t0 + o.d + 0.05);
  },
  /* ---- sound effects ---- */
  shoot() { this.tone({ f: 300, f2: 860, d: 0.17, v: 0.22, rev: 0.2 }); this.tone({ f: 620, f2: 1500, d: 0.1, v: 0.05, type: 'triangle' }); this.noise({ f: 2200, f2: 500, d: 0.12, v: 0.05 }); },
  bounce() { this.tone({ f: 1250, f2: 900, d: 0.07, v: 0.07, type: 'triangle' }); },
  stick() { this.tone({ f: 250, f2: 170, d: 0.11, v: 0.18 }); this.noise({ ft: 'lowpass', f: 900, d: 0.05, v: 0.05 }); },
  pop(i) {
    const sc = [0, 2, 4, 7, 9, 12, 14, 16, 19, 21, 24];
    const f = midi(76 + sc[Math.min(i, sc.length - 1)]);
    this.tone({ f: f * 1.5, f2: f * 0.75, d: 0.09, v: 0.13, t: i * 0.035, rev: 0.25 });
    this.noise({ ft: 'highpass', f: 3500, d: 0.035, v: 0.05, t: i * 0.035 });
  },
  fish(n) { for (let i = 0; i < Math.min(6, 2 + (n >> 1)); i++) this.tone({ f: midi(79 + [0, 2, 4, 7, 9, 12][i]), d: 0.22, v: 0.06, t: 0.12 + i * 0.06, type: 'triangle', rev: 0.5 }); },
  drop() { this.tone({ f: 95, f2: 50, d: 0.4, v: 0.32 }); this.noise({ ft: 'lowpass', f: 500, f2: 120, d: 0.35, v: 0.14 }); },
  warn() { this.tone({ f: 523, d: 0.1, v: 0.05, type: 'triangle' }); this.tone({ f: 523, d: 0.1, v: 0.05, type: 'triangle', t: 0.14 }); },
  swap() { this.tone({ f: 620, d: 0.07, v: 0.09 }); this.tone({ f: 830, d: 0.08, v: 0.09, t: 0.06 }); },
  rainbow() { [1047, 1319, 1568, 2093, 2637].forEach((f, i) => this.tone({ f, d: 0.35, v: 0.06, t: i * 0.045, rev: 0.7 })); },
  bomb() { this.noise({ ft: 'lowpass', f: 1600, f2: 90, d: 0.7, v: 0.5, q: 0.7 }); this.tone({ f: 130, f2: 38, d: 0.55, v: 0.4 }); },
  zap() { this.tone({ f: 1900, f2: 180, d: 0.28, v: 0.07, type: 'sawtooth' }); this.noise({ ft: 'highpass', f: 2500, d: 0.25, v: 0.12 }); this.tone({ f: 70, d: 0.3, v: 0.2, type: 'square', t: 0.02 }); },
  ice() { for (let i = 0; i < 3; i++) this.noise({ f: 5200 + i * 700, q: 9, d: 0.07, v: 0.16, t: i * 0.045 }); this.tone({ f: 2600, d: 0.08, v: 0.04, t: 0.05 }); },
  click() { this.tone({ f: 880, d: 0.06, v: 0.07, type: 'triangle' }); },
  move() { this.tone({ f: 660, d: 0.04, v: 0.04, type: 'triangle' }); },
  combo(n) { this.tone({ f: midi(72 + Math.min(n, 8) * 2), d: 0.25, v: 0.08, type: 'triangle', rev: 0.5 }); },
  star(i) { this.tone({ f: midi(84 + i * 4), d: 0.45, v: 0.13, rev: 0.6 }); this.tone({ f: midi(96 + i * 4), d: 0.3, v: 0.03, rev: 0.6 }); },
  clear() { [72, 76, 79, 84, 88].forEach((m, i) => this.tone({ f: midi(m), d: 0.5, v: 0.1, t: i * 0.09, type: 'triangle', rev: 0.6 })); [72, 76, 79].forEach((m) => this.tone({ f: midi(m), d: 1.4, v: 0.06, t: 0.5, rev: 0.6 })); },
  fail() { [67, 63, 60, 55].forEach((m, i) => this.tone({ f: midi(m), d: 0.6, v: 0.09, t: i * 0.22, type: 'triangle', rev: 0.5 })); },
  /* ---- background music: slow underwater arpeggio + soft pad ---- */
  schedule() {
    const c = this.ctx; if (!c) return;
    const spb = 60 / 78 / 2;
    while (this.nextT < c.currentTime + 0.35) { this.playStep(this.step, this.nextT, spb); this.nextT += spb; this.step = (this.step + 1) % 64; }
  },
  playStep(s, at, spb) {
    const CH = [[55, 59, 62, 66], [54, 57, 61, 64], [52, 55, 59, 62], [57, 61, 64, 66], [55, 59, 62, 67], [54, 57, 62, 64], [52, 55, 59, 64], [50, 57, 62, 66]];
    const BASS = [43, 42, 40, 45, 43, 42, 40, 38];
    const bar = s >> 3, b = s & 7, ch = CH[bar], mg = this.musG;
    if (b === 0) {
