    if (b !== 7 || bar % 2 === 0) {
      const m = ch[arp[b]] + 12;
      this.tone({ music: 1, at, f: midi(m), d: 0.55, a: 0.006, v: 0.045, dest: mg, rev: 0.35 });
      this.tone({ music: 1, at, f: midi(m) * 4, d: 0.12, a: 0.003, v: 0.008, dest: mg });
    }
    const rn = this.melRng;
