  for (const p of CREATURES[idx]) {
    const k = p[0], d = p[1], w = p[2];
    if (k === 'f') el('path', { d, fill: ink, opacity: 0.8 }, g);
    else if (k === 'l') el('path', { d, fill: light, opacity: 0.92 }, g);
    else if (k === 's') el('path', { d, fill: 'none', stroke: ink, 'stroke-width': w, 'stroke-linecap': 'round', opacity: 0.8 }, g);
    else el('path', { d, fill: 'none', stroke: light, 'stroke-width': w, 'stroke-linecap': 'round', 'stroke-linejoin': 'round', opacity: 0.85 }, g);
