  el('path', { d: wobbleCircle(0, 0, 18.8, 0.9, 18, seed + 7), fill: 'none', stroke: K, 'stroke-width': 1.8, opacity: 0.78 }, s);
  el('path', { d: 'M-13.5 12.5A18.4 18.4 0 0 0 13.5 12.5', fill: 'none', stroke: I, 'stroke-width': 1.7, 'stroke-linecap': 'round', opacity: 0.35 }, s);
}
function bubbleGloss(s) {
