  el('circle', { cx: -12.8, cy: -2.6, r: 1.7, fill: '#fff', opacity: 0.75 }, s);
  el('path', { d: 'M-16.2-6.4A17.6 17.6 0 0 1-6.4-16.4', fill: 'none', stroke: '#fff', 'stroke-width': 1.3, 'stroke-linecap': 'round', opacity: 0.55 }, s);
