  el('circle', { r: 19.3, fill: 'url(#gPearl)' }, s);
  el('path', { d: wobbleCircle(0, 0, 18.8, 0.9, 18, 401), fill: 'none', stroke: '#7d62a8', 'stroke-width': 1.6, opacity: 0.55 }, s);
  el('path', { d: SPARK_D, fill: '#fff', opacity: 0.95 }, s);
