  el('circle', { r: 19.3, fill: 'url(#gBomb)' }, s);
  el('path', { d: wobbleCircle(0, 0, 18.8, 0.9, 18, 402), fill: 'none', stroke: '#10151f', 'stroke-width': 1.8, opacity: 0.7 }, s);
