  el('path', { d: circlePath(-2.6, 4.4, 1) + circlePath(0.6, 6, 0.9) + circlePath(-4, 0.6, 0.8), fill: '#d8bf8c' }, s);
  el('path', { d: circlePath(3.6, -1, 1.6), fill: '#27324a' }, s);
