  el('path', { d: 'M0-6.4C0.6-9.8 2.6-11.4 4.6-12.4', fill: 'none', stroke: '#c8a064', 'stroke-width': 1.5, 'stroke-linecap': 'round' }, s);
  el('path', { d: SPARK_D, fill: '#ffcf4a', transform: 'translate(5.4 -13) scale(.42)' }, s);
  bubbleGloss(s);
  // lightning bubble
