  el('circle', { r: 19.3, fill: 'url(#gZap)' }, s);
  el('path', { d: wobbleCircle(0, 0, 18.8, 0.9, 18, 403), fill: 'none', stroke: '#b86a12', 'stroke-width': 1.8, opacity: 0.7 }, s);
  el('path', { d: BOLT_D, fill: '#5a3a8e', stroke: '#fff7d0', 'stroke-width': 1.2, 'stroke-linejoin': 'round', opacity: 0.92 }, s);
