  el('path', { d: hx + 'Z', fill: 'url(#gIce)', stroke: '#ffffff', 'stroke-width': 2, 'stroke-linejoin': 'round', opacity: 0.95 }, s);
  el('path', { d: 'M0 0L0-21.5M0 0L18.6 10.7M0 0L-18.6 10.7M0 0L-18.6-10.7M0 0L18.6-10.7M0 0L0 21.5', stroke: '#ffffff', 'stroke-width': 1, opacity: 0.45 }, s);
  el('path', { d: 'M-14-8L-3-18L-1-12L-11-3Z', fill: '#fff', opacity: 0.55 }, s);
  el('path', { d: 'M9 6L14 3M11 9.5L16 8', stroke: '#fff', 'stroke-width': 1.4, 'stroke-linecap': 'round', opacity: 0.8 }, s);
  // landing ghost
  s = el('g', { id: 'ghost' }, DEFS);
  el('circle', { r: 17.5, fill: '#ffffff', 'fill-opacity': 0.16, stroke: '#ffffff', 'stroke-width': 2, 'stroke-dasharray': '4 4', opacity: 0.9 }, s);
  // star
  s = el('path', { id: 'star', d: (() => { let d = ''; for (let i = 0; i < 10; i++) { const a = -Math.PI / 2 + (i * Math.PI) / 5, r = i % 2 ? 4.6 : 11; d += (i ? 'L' : 'M') + f1(Math.cos(a) * r) + ' ' + f1(Math.sin(a) * r); } return d + 'Z'; })(), 'stroke-linejoin': 'round' }, DEFS);
}
const bubHref = (b) => (b.t === 'n' ? '#b' + b.c : '#b' + b.t);

/* ============ art: background (static, filters allowed) ============ */
function buildBackground() {
  const g = $('bgStatic');
  el('rect', { width: W, height: H, fill: '#efe6d3' }, g);
  const wash = el('g', { filter: 'url(#fWash)' }, g);
  el('rect', { x: 10, y: 8, width: W - 20, height: H - 16, fill: 'url(#gWater)' }, wash);
  const bl = el('g', { filter: 'url(#fBloom)', opacity: 0.55 }, g);
  [[170, 170, 220, 120, '#8fd2c9'], [1100, 150, 230, 110, '#a3dad2'], [250, 470, 270, 150, '#4f95a8'], [1040, 470, 290, 150, '#4a8ea6'],
    [640, 330, 320, 180, '#a6d8d2'], [110, 650, 230, 90, '#3c7c94'], [1180, 650, 230, 90, '#3a7a93'], [660, 70, 300, 70, '#eef6dc'], [430, 620, 160, 70, '#5a9fb0'], [860, 250, 150, 90, '#7cc0c3']]
    .forEach((b) => el('path', { d: wobbleCircle(0, 0, 1, 0.18, 14, b[0] | 0), transform: 'translate(' + b[0] + ' ' + b[1] + ') scale(' + b[2] + ' ' + b[3] + ')', fill: b[4] }, bl));
  el('ellipse', { cx: 540, cy: -30, rx: 560, ry: 270, fill: 'url(#gSun)' }, g);
  // distant reef silhouettes
  const far = el('g', { filter: 'url(#fSoft)' }, g);
  const ridge = (y0, amp, col, op, seed) => {
    const rn = mulberry(seed); let d = 'M-20 ' + H, x = -20;
    while (x < W + 40) { const y = y0 - rn() * amp; d += 'Q' + f1(x + 30) + ' ' + f1(y - 30 * rn()) + ' ' + f1(x + 60) + ' ' + f1(y); x += 60 + rn() * 50; }
    el('path', { d: d + 'L' + (W + 40) + ' ' + H + 'Z', fill: col, opacity: op }, far);
  };
  ridge(520, 90, '#8dbdc3', 0.5, 5); ridge(600, 70, '#6ea4ae', 0.5, 8);
  const tree = (x, y, len, ang, dep, out) => {
    const x2 = x + Math.cos(ang) * len, y2 = y + Math.sin(ang) * len;
    out.push('M' + f1(x) + ' ' + f1(y) + 'L' + f1(x2) + ' ' + f1(y2));
    if (dep > 0) { tree(x2, y2, len * 0.72, ang - R2(0.25, 0.6), dep - 1, out); tree(x2, y2, len * 0.72, ang + R2(0.25, 0.6), dep - 1, out); }
  };
  [[150, 560, 60], [345, 590, 45], [930, 575, 55], [1180, 560, 62], [60, 600, 40]].forEach((t) => {
    const out = []; tree(t[0], t[1], t[2], -Math.PI / 2, 4, out);
    el('path', { d: out.join(''), stroke: '#7fb1b8', 'stroke-width': 5, 'stroke-linecap': 'round', fill: 'none', opacity: 0.55 }, far);
  });
  // sand floor
  const sand = el('g', { filter: 'url(#fSoft)' }, g);
  let sd = 'M-20 ' + H + 'L-20 690';
  for (let x = -20; x <= W + 40; x += 40) sd += 'Q' + (x + 20) + ' ' + f1(682 + Math.sin(x * 0.013) * 7 + R2(-3, 3)) + ' ' + (x + 40) + ' ' + f1(688 + Math.sin((x + 40) * 0.013) * 7);
  el('path', { d: sd + 'L' + (W + 40) + ' ' + H + 'Z', fill: 'url(#gSand)' }, sand);
  for (let i = 0; i < 70; i++) { const x = R2(0, W), y = R2(694, 716); el('ellipse', { cx: f1(x), cy: f1(y), rx: f1(R2(1.5, 5)), ry: f1(R2(1, 3)), fill: ['#c9a874', '#b99463', '#e9d7b0', '#a9855a'][i % 4], opacity: 0.7 }, sand); }
  [[70, 704, '#f1c7b7'], [1220, 706, '#efd6c1'], [300, 708, '#e9c7cf']].forEach((s) => {
    const sg = el('g', { transform: 'translate(' + s[0] + ' ' + s[1] + ')' }, sand);
    el('path', { d: 'M-9 3C-9-5 9-5 9 3Z', fill: s[2] }, sg);
    el('path', { d: 'M-6 2L-3-4M0 2L0-5M6 2L3-4', stroke: '#b8826f', 'stroke-width': 1, opacity: 0.6 }, sg);
  });
}

/* ============ art: light spots / rays (animated, no filters) ============ */
const LIGHT = { rays: [], spots: [] };
function buildLight() {
  const g = $('lightG');
  for (let i = 0; i < 6; i++) {
    const x = 60 + i * 215 + R2(-40, 40), w = R2(45, 100);
    const p = el('path', { d: 'M' + f1(x) + ' -10L' + f1(x + w) + ' -10L' + f1(x + w * 2.4 + 170) + ' 730L' + f1(x + w * 1.1 + 150) + ' 730Z', fill: 'url(#gRay)', opacity: 0.4 }, g);
    LIGHT.rays.push({ p, ph: R2(0, TAU), sp: R2(0.18, 0.34) });
  }
  for (let i = 0; i < 18; i++) {
    const low = i >= 12;
    const s = { x: low ? R2(20, W - 20) : R2(0, W), y: low ? R2(686, 712) : R2(30, 420), rx: low ? R2(26, 50) : R2(40, 90), ry: low ? R2(5, 9) : R2(14, 30), ph: R2(0, TAU), sp: R2(0.3, 0.7) };
    s.e = el('ellipse', { cx: s.x, cy: s.y, rx: s.rx, ry: s.ry, fill: 'url(#gSpot)', opacity: low ? 0.7 : 0.55 }, g);
    LIGHT.spots.push(s);
  }
}
function updateLight(t) {
  for (const r of LIGHT.rays) { const v = Math.sin(t * r.sp + r.ph); r.p.setAttribute('opacity', (Math.round((0.3 + 0.2 * v) * 100) / 100) + ''); r.p.setAttribute('transform', 'translate(' + f1(v * 14) + ' 0)'); }
  for (const s of LIGHT.spots) {
    const a = t * s.sp + s.ph;
    s.e.setAttribute('cx', f1(s.x + Math.sin(a) * 22)); s.e.setAttribute('cy', f1(s.y + Math.cos(a * 0.8) * 7));
    s.e.setAttribute('rx', f1(s.rx * (0.85 + 0.15 * Math.sin(a * 1.7))));
  }
}

/* ============ art: coral / seaweed / fish / bubbles (animated) ============ */
const SCN = { weeds: [], corals: [], fish: [], amb: [], anem: [] };
function branchCoral(parent, x, y, size, col, seed, spread) {
  const rn = mulberry(seed), g = el('g', {}, parent), lv = [[], [], [], [], []], tips = [];
  const grow = (px, py, ang, len, dep) => {
    const x2 = px + Math.cos(ang) * len, y2 = py + Math.sin(ang) * len;
    const mx = (px + x2) / 2 + (rn() - 0.5) * len * 0.35, my = (py + y2) / 2;
    lv[4 - dep].push('M' + f1(px) + ' ' + f1(py) + 'Q' + f1(mx) + ' ' + f1(my) + ' ' + f1(x2) + ' ' + f1(y2));
    if (dep === 0) { tips.push([x2, y2]); return; }
    const n = rn() < 0.35 ? 3 : 2;
    for (let k = 0; k < n; k++) grow(x2, y2, ang + (k - (n - 1) / 2) * spread + (rn() - 0.5) * 0.3, len * (0.68 + rn() * 0.12), dep - 1);
  };
  grow(0, 0, -Math.PI / 2 + (rn() - 0.5) * 0.2, size * 0.36, 4);
  const L = mix(col, '#ffffff', 0.35), K = shade(col, -0.25);
  lv.forEach((segs, i) => el('path', { d: segs.join(''), stroke: L, 'stroke-width': f1((5 - i) * size * 0.03 + 5), 'stroke-linecap': 'round', fill: 'none', opacity: 0.45 }, g));
  lv.forEach((segs, i) => el('path', { d: segs.join(''), stroke: col, 'stroke-width': f1((5 - i) * size * 0.022 + 2), 'stroke-linecap': 'round', fill: 'none', opacity: 0.88 }, g));
  lv.forEach((segs, i) => el('path', { d: segs.join(''), stroke: K, 'stroke-width': 1.1, 'stroke-linecap': 'round', fill: 'none', opacity: 0.35, transform: 'translate(1.5 0.5)' }, g));
  el('path', { d: tips.map((p) => circlePath(f1(p[0]), f1(p[1]), 3)).join(''), fill: L, opacity: 0.9 }, g);
  SCN.corals.push({ g, x, y, ph: rn() * TAU, amp: 1.4 });
  g.setAttribute('transform', 'translate(' + x + ' ' + y + ')');
  return g;
}
function seaFan(parent, x, y, size, col, seed) {
  const rn = mulberry(seed), g = el('g', {}, parent), segs = [];
  el('path', { d: wobbleCircle(0, -size * 0.55, size * 0.5, size * 0.06, 16, seed), transform: 'scale(1 1.05)', fill: col, opacity: 0.22 }, g);
  const grow = (px, py, ang, len, dep) => {
    const x2 = px + Math.cos(ang) * len, y2 = py + Math.sin(ang) * len;
    segs.push('M' + f1(px) + ' ' + f1(py) + 'L' + f1(x2) + ' ' + f1(y2));
    if (dep > 0) { grow(x2, y2, ang - 0.32 - rn() * 0.2, len * 0.78, dep - 1); grow(x2, y2, ang + 0.32 + rn() * 0.2, len * 0.78, dep - 1); }
  };
  grow(0, 0, -Math.PI / 2, size * 0.26, 6);
  el('path', { d: segs.join(''), stroke: col, 'stroke-width': 2.2, 'stroke-linecap': 'round', fill: 'none', opacity: 0.8 }, g);
  el('path', { d: segs.join(''), stroke: mix(col, '#ffffff', 0.4), 'stroke-width': 0.9, fill: 'none', opacity: 0.7, transform: 'translate(-1 -1)' }, g);
  SCN.corals.push({ g, x, y, ph: rn() * TAU, amp: 3.2 });
  g.setAttribute('transform', 'translate(' + x + ' ' + y + ')');
}
function brainCoral(parent, x, y, w, h, col, seed) {
  const rn = mulberry(seed), g = el('g', { transform: 'translate(' + x + ' ' + y + ')' }, parent);
  el('path', { d: 'M' + -w / 2 + ' 0C' + -w / 2 + ' ' + -h * 1.3 + ' ' + w / 2 + ' ' + -h * 1.3 + ' ' + w / 2 + ' 0Z', fill: col, opacity: 0.9 }, g);
  el('path', { d: 'M' + (-w / 2 + 6) + ' -4C' + (-w / 2 + 8) + ' ' + -h * 1.05 + ' ' + (w / 2 - 8) + ' ' + -h * 1.05 + ' ' + (w / 2 - 6) + ' -4', fill: 'none', stroke: mix(col, '#fff', 0.45), 'stroke-width': 4, opacity: 0.5 }, g);
  let d = '';
  for (let i = 0; i < 7; i++) { const yy = -h * (0.15 + i * 0.12), hw = (w / 2) * Math.sqrt(Math.max(0, 1 - Math.pow((i * 0.12 + 0.15) / 1, 2))) * 0.85; let xx = -hw; d += 'M' + f1(xx) + ' ' + f1(yy); while (xx < hw) { xx += 8; d += 'Q' + f1(xx - 4) + ' ' + f1(yy + (rn() - 0.5) * 9) + ' ' + f1(xx) + ' ' + f1(yy); } }
  el('path', { d, fill: 'none', stroke: shade(col, -0.3), 'stroke-width': 1.4, opacity: 0.55 }, g);
}
function tubeSponge(parent, x, y, col, seed) {
  const rn = mulberry(seed), g = el('g', { transform: 'translate(' + x + ' ' + y + ')' }, parent);
  for (let i = 0; i < 4; i++) {
    const tx = (i - 1.5) * 13 + (rn() - 0.5) * 4, th = 36 + rn() * 38, tw = 6 + rn() * 3;
    el('path', { d: 'M' + f1(tx - tw) + ' 0L' + f1(tx - tw + 2) + ' ' + f1(-th) + 'L' + f1(tx + tw - 2) + ' ' + f1(-th) + 'L' + f1(tx + tw) + ' 0Z', fill: col, opacity: 0.85 }, g);
    el('ellipse', { cx: f1(tx), cy: f1(-th), rx: f1(tw - 1.5), ry: 3, fill: shade(col, -0.35), opacity: 0.75 }, g);
    el('path', { d: 'M' + f1(tx - tw + 3) + ' -4L' + f1(tx - tw + 4) + ' ' + f1(-th + 6), stroke: mix(col, '#fff', 0.5), 'stroke-width': 2, opacity: 0.6 }, g);
  }
}
function anemone(parent, x, y, col, n, seed) {
  const rn = mulberry(seed), g = el('g', { transform: 'translate(' + x + ' ' + y + ')' }, parent);
  const tent = [];
  for (let i = 0; i < n; i++) tent.push({ a: -Math.PI / 2 + (i / (n - 1) - 0.5) * 2.2, len: 26 + rn() * 14, ph: rn() * TAU, p: el('path', { fill: 'none', stroke: i % 2 ? col : mix(col, '#fff', 0.3), 'stroke-width': 4.5, 'stroke-linecap': 'round', opacity: 0.85 }, g) });
  el('path', { d: 'M-18 2C-16-12 16-12 18 2Z', fill: shade(col, -0.25), opacity: 0.95 }, g);
