function updateScenery(t, dt) {
  for (const w of SCN.weeds) {
    let L = '', Rr = '', C = '';
    for (let k = 0; k <= w.n; k++) {
      const f = k / w.n, y = 712 - f * w.h;
      const x = w.x + Math.sin(t * w.sp + w.ph - f * 2.2) * w.amp * f * f + Math.sin(t * 2.1 + f * 5 + w.ph) * 2 * f;
      const wd = w.wd * (1 - f * 0.85) * (0.8 + 0.25 * Math.sin(f * 9 + w.ph));
      L += (k ? 'L' : 'M') + f1(x - wd) + ' ' + f1(y); Rr = 'L' + f1(x + wd) + ' ' + f1(y) + Rr; C += (k ? 'L' : 'M') + f1(x) + ' ' + f1(y);
    }
    const d = L + Rr + 'Z';
    w.p.setAttribute('d', d); w.p2.setAttribute('d', d); w.p2.setAttribute('transform', 'translate(' + f1(4 + Math.sin(t + w.ph) * 2) + ' 2)'); w.p3.setAttribute('d', C);
  }
  for (const c of SCN.corals) c.g.setAttribute('transform', 'translate(' + c.x + ' ' + c.y + ') rotate(' + f1(Math.sin(t * 0.7 + c.ph) * c.amp) + ')');
  for (const a of SCN.anem) for (const tn of a.tent) {
    const sw = Math.sin(t * 1.4 + tn.ph) * 0.35, a1 = tn.a + sw * 0.5, a2 = tn.a + sw;
    const x1 = Math.cos(a1) * tn.len * 0.5, y1 = Math.sin(a1) * tn.len * 0.5 - 6, x2 = x1 + Math.cos(a2) * tn.len * 0.5, y2 = y1 + Math.sin(a2) * tn.len * 0.5;
    tn.p.setAttribute('d', 'M0 -6Q' + f1(x1) + ' ' + f1(y1) + ' ' + f1(x2) + ' ' + f1(y2));
  }
  for (const f of SCN.fish) {
    f.x += f.sp * dt;
    if (f.sp > 0 && f.x > W + 120) { f.x = -160; f.y = R2(360, 600); }
    if (f.sp < 0 && f.x < -160) { f.x = W + 120; f.y = R2(360, 600); }
    f.g.setAttribute('transform', 'translate(' + f1(f.x) + ' ' + f1(f.y + Math.sin(t * 0.8 + f.ph) * 8) + ') scale(' + (f.sp > 0 ? f.s : -f.s) + ' ' + f.s + ')');
  }
  for (const b of SCN.amb) {
    b.y -= b.sp * dt;
    if (b.y < -10) { b.y = H + 10; b.x = R2(10, W - 10); }
    b.e.setAttribute('cx', f1(b.x + Math.sin(t * 1.5 + b.ph) * 5)); b.e.setAttribute('cy', f1(b.y));
  }
}
