    const cols = new Set();
    for (const n of neighbors(r, c)) { const m = G.grid[n[0]][n[1]]; if (m && m.t === 'n' && !m.ice) cols.add(m.c); }
    for (const col of cols) { const grp = flood(r, c, col); if (grp.length >= 3) { grp.forEach((p) => add(p[0], p[1])); matched = true; } }
    if (matched) { AU.rainbow(); fxSparkle(gx, gy); }
  } else {
    const grp = flood(r, c, cell.c);
    if (grp.length >= 3) { grp.forEach((p) => add(p[0], p[1])); matched = true; }
  }
  if (hit) { const h = G.grid[hit[0]][hit[1]]; if (h && (h.t === 'B' || h.t === 'L')) trigger(hit[0], hit[1]); }
  if (matched) for (const p of [...pop.values()]) for (const n of neighbors(p[0], p[1])) { const m = G.grid[n[0]][n[1]]; if (m && (m.t === 'B' || m.t === 'L')) trigger(n[0], n[1]); }
  let thawed = 0;
  for (const n of neighbors(r, c)) { const m = G.grid[n[0]][n[1]]; if (m && m.ice && !pop.has(key(n[0], n[1]))) { thaw(m, n[0], n[1]); thawed++; } }
  if (thawed) AU.ice();
  // apply pops
  const list = [...pop.values()].sort((p, q) => Math.hypot(cellX(p[0], p[1]) - gx, cellYL(p[0]) - cellYL(r)) - Math.hypot(cellX(q[0], q[1]) - gx, cellYL(q[0]) - cellYL(r)));
  list.forEach((p, i) => { const m = G.grid[p[0]][p[1]]; G.grid[p[0]][p[1]] = null; fxPop(m, p[0], p[1], i * 0.035); if (i < 12) AU.pop(i); });
  const fall = findFloating();
  let fx = 0, fy = 0;
  fall.forEach((p) => { const m = G.grid[p[0]][p[1]]; G.grid[p[0]][p[1]] = null; fx += cellX(p[0], p[1]); fy += cellYL(p[0]); fxFall(m, p[0], p[1]); });
  const nP = list.length, nF = fall.length;
  if (nP || nF) {
    G.combo = matched || trig.size ? G.combo + 1 : G.combo;
    G.maxCombo = Math.max(G.maxCombo, G.combo);
    const mult = 1 + Math.max(0, G.combo - 1) * 0.5;
    const pp = Math.round(nP * 10 * mult), fp = nF ? 20 * nF * (1 + Math.floor(nF / 4)) : 0;
    G.score += pp + fp; G.popped += nP; G.dropped += nF;
    if (pp) popup(gx, gy - 26, '+' + fmt(pp), '#ffffff', 22);
    if (G.combo >= 2) { popup(gx, gy - 54, '\u8fde\u51fb \u00d7' + G.combo, '#ffe9a8', 20); AU.combo(G.combo); }
    if (nF) { popup(fx / nF, G.ceilVis + fy / nF, '\u5c0f\u9c7c\u6e38\u8d70 +' + fmt(fp), '#c9fff0', 22); AU.fish(nF); }
    if (nF >= 6 && !G.bonus) {
      const allowed = G.mode === 'end' ? 'RBL' : LEVELS[G.lv].sp || 'R';
      G.bonus = { t: allowed[Math.floor(Math.random() * allowed.length)], c: -1 };
      popup(640, 360, '\u5956\u52b1\uff1a' + ({ R: '\u5f69\u8679\u6ce1', B: '\u70b8\u5f39\u6ce1', L: '\u95ea\u7535\u6ce1' })[G.bonus.t] + '\uff01', '#fff2b0', 26);
    }
  } else G.combo = 0;
}
function thaw(m, r, c) {
  m.ice = false;
  if (m.iceE) { const x = cellX(r, c), y = G.ceilVis + G.shift + cellYL(r); m.iceE.remove(); m.iceE = null; fxShards(x, y); }
}
function afterShot() {
  G.shots++;
  if (G.over) return;
  if (G.mode === 'adv' && cellCount() === 0) { win(); updateHUD(); return; }
  G.dropIn--;
  if (G.dropIn <= 0) { G.dropIn = G.dropEvery; doDrop(); }
  if (G.mode === 'end') {
    ensureRows();
    G.dropEvery = Math.max(DIFFS[G.diff].endMin, DIFFS[G.diff].endDrop - Math.floor(G.score / 4000));
    if (G.dropIn > G.dropEvery) G.dropIn = G.dropEvery;
    buildPips();
  }
  if (G.dropIn === 1) AU.warn();
  rerollMissing(); checkLose(); updateHUD(); G.aimDirty = true;
}
function doDrop() {
  if (G.mode === 'adv') G.ceil += ROWH; else insertRow();
  AU.drop(); G.shake = Math.max(G.shake, 0.35);
}
function insertRow() {
  if (G.land) { G.land.cell.e.removeAttribute('transform'); G.land = null; }
  G.parity ^= 1;
  const last = G.grid.pop();
  last.forEach((k) => { if (k) { k.e.remove(); if (k.iceE) k.iceE.remove(); } });
  G.grid.unshift(emptyRow());
  G.grid[0] = genRow(0, Math.random, 0.05, 0.012);
  eachCell((k, r, c) => { if (r === 0) makeCellEl(k, r, c); else posCellEl(k, r, c); });
  G.shift -= ROWH; G.rowsPushed++;
}
function ensureRows() {
  let lo = lowestRow();
  if (lo < 0) { G.score += 2000; popup(640, 300, '\u6e05\u5c4f\u5956\u52b1 +2,000', '#fff2b0', 28); }
  let n = 0;
  while (lo < 3 && n < 5) { insertRow(); lo++; n++; }
}
function lowestRow() { for (let r = MAX_ROWS - 1; r >= 0; r--) for (let c = 0; c < COLS; c++) if (G.grid[r][c]) return r; return -1; }
function checkLose() {
  const r = lowestRow(); if (r < 0) { G.danger = 0; return; }
  const bottom = G.ceil + cellYL(r) + R;
  G.danger = bottom > DEAD_Y - ROWH * 2.2 ? 1 : 0;
  if (bottom > DEAD_Y + 1) lose();
}
function win() {
  G.over = true;
  const bonus = 1000 + Math.max(0, G.par - G.shots) * 50;
  G.score += bonus; popup(640, 330, '\u6e05\u573a\u5956\u52b1 +' + fmt(bonus), '#fff2b0', 30);
  const stars = G.shots <= G.par ? 3 : G.shots <= Math.round(G.par * 1.4) ? 2 : 1, d = G.diff, i = G.lv;
  G.rec = { stars, best: Math.max(SAVE.lvBest[d][i], G.score), newBest: G.score > SAVE.lvBest[d][i], last: i === 11 };
  SAVE.stars[d][i] = Math.max(SAVE.stars[d][i], stars); SAVE.lvBest[d][i] = Math.max(SAVE.lvBest[d][i], G.score);
  if (i + 1 < 12) SAVE.unlock[d] = Math.max(SAVE.unlock[d], i + 2);
  writeSave();
  AU.clear(); CRAB.mood = 1;
  for (let k = 0; k < 16; k++) spawnFish(R2(FL + 30, FR - 30), R2(150, 520), k % G.nc, 0.05 * k);
  G.endTimer = 1.7; G.endKind = 'clear';
}
function lose() {
  if (G.over) return;
  G.over = true; AU.fail(); CRAB.mood = -1; G.danger = 0;
  let i = 0;
  eachCell((k, r, c) => { G.grid[r][c] = null; fxSink(k, r, c, (i++ % 40) * 0.02); });
  if (G.shot) { G.shot.e.remove(); G.shot = null; }
  if (G.mode === 'end') { const d = G.diff; G.rec = { best: Math.max(SAVE.endBest[d], G.score), newBest: G.score > SAVE.endBest[d] }; SAVE.endBest[d] = G.rec.best; writeSave(); G.endKind = 'endless'; }
  else { G.rec = { best: SAVE.lvBest[G.diff][G.lv] }; G.endKind = 'fail'; }
  G.endTimer = 1.9;
}
/* aim guide: path including the segment after the first bounce */
function computeTrace() {
  let x = LX, y = LY, vx = Math.sin(G.aim), vy = -Math.cos(G.aim), b = 0, landAt = null;
  const p1 = [[x, y]], p2 = [];
  for (let i = 0; i < 420; i++) {
    x += vx * 5; y += vy * 5;
    if (x < FL + R || x > FR - R) {
      const wx = x < FL + R ? FL + R : FR - R; x = 2 * wx - x; vx = -vx;
      if (b === 0) { p1.push([wx, y]); p2.push([wx, y]); b = 1; continue; }
      p2.push([wx, y]); b = 2; break;
    }
    if (y <= G.ceil + R) { landAt = snapCell(x, G.ceil + R, null); break; }
    const h = collide(x, y); if (h) { landAt = snapCell(x, y, h); break; }
  }
  if (b < 2) (b === 0 ? p1 : p2).push([x, y]);
  const pd = (p) => (p.length > 1 ? p.map((q, i) => (i ? 'L' : 'M') + f1(q[0]) + ' ' + f1(q[1])).join('') : '');
  AIM.l1.setAttribute('d', pd(p1)); AIM.l2.setAttribute('d', pd(p2));
  if (landAt) setA(AIM.ghost, { x: f1(cellX(landAt[0], landAt[1])), y: f1(cellY(landAt[0])), 'data-on': 1 });
  else AIM.ghost.removeAttribute('data-on');
}
const AIM = {};
function buildAim() {
  const g = $('aimG');
  AIM.l2 = el('path', { fill: 'none', stroke: '#ffffff', 'stroke-width': 4.5, 'stroke-linecap': 'round', 'stroke-dasharray': '0.1 13', opacity: 0.5 }, g);
  AIM.l1 = el('path', { fill: 'none', stroke: '#ffffff', 'stroke-width': 5, 'stroke-linecap': 'round', 'stroke-dasharray': '0.1 13', opacity: 0.9 }, g);
  AIM.ghost = el('use', { href: '#ghost', x: 0, y: 0, class: 'hidden' }, g);
}
/* ============ effects: droplets / ripples / fish / ice shards / lightning ============ */
const FX = { drops: [], rings: [], texts: [], items: [], pops: [], tweens: [], temp: [] };
function initFx() {
  const g = $('fxG');
  for (let i = 0; i < 170; i++) FX.drops.push({ e: el('circle', { r: 3, class: 'hidden' }, g), live: false });
  for (let i = 0; i < 26; i++) FX.rings.push({ e: el('circle', { fill: 'none', 'stroke-width': 2.5, class: 'hidden' }, g), live: false });
  for (let i = 0; i < 12; i++) FX.texts.push({ e: text(g, 0, 0, '', 22, { 'text-anchor': 'middle', 'font-weight': 800, class: 'hidden', stroke: '#1d3f4a', 'stroke-width': 4.5, 'paint-order': 'stroke', 'stroke-linejoin': 'round' }), live: false });
}
function clearFx() {
  for (const a of [FX.drops, FX.rings, FX.texts]) for (const d of a) { d.live = false; d.e.classList.add('hidden'); }
  for (const it of FX.items) it.e.remove();
  for (const p of FX.pops) { p.cell.e.remove(); if (p.cell.iceE) p.cell.iceE.remove(); }
  for (const t of FX.temp) t.e.remove();
  FX.items = []; FX.pops = []; FX.temp = []; FX.tweens = [];
}
function tween(e, dur, fn, done) { FX.tweens = FX.tweens.filter((t) => t.e !== e); FX.tweens.push({ e, t: 0, dur, fn, done }); }
function spawnDrops(x, y, col, n, spd) {
  for (let i = 0; i < n; i++) {
    const d = FX.drops.find((q) => !q.live); if (!d) return;
    const a = Math.random() * TAU, v = (spd || 160) * (0.35 + Math.random() * 0.8);
    Object.assign(d, { live: true, x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v - 50, r: 1.6 + Math.random() * 3.2, t: 0, life: 0.45 + Math.random() * 0.4 });
    d.e.setAttribute('fill', col); d.e.classList.remove('hidden');
  }
}
function spawnRing(x, y, col, r0, r1, life) {
  const g = FX.rings.find((q) => !q.live); if (!g) return;
  Object.assign(g, { live: true, x, y, r0, r1, t: 0, life });
  setA(g.e, { cx: f1(x), cy: f1(y), stroke: col }); g.e.classList.remove('hidden');
}
function popup(x, y, str, col, size) {
  const p = FX.texts.find((q) => !q.live) || FX.texts[0];
  Object.assign(p, { live: true, x, y, t: 0, life: 1.25 });
  p.e.textContent = str; p.e.style.fill = col; setA(p.e, { 'font-size': size || 22, x: f1(x), y: f1(y) }); p.e.classList.remove('hidden');
}
function colorOf(cell) {
  if (cell.t === 'n') return COLORS[cell.c];
  if (cell.t === 'R') return { base: COLORS[Math.floor(Math.random() * 6)].base, L: '#ffffff' };
  if (cell.t === 'B') return { base: '#48566f', L: '#c3cedd' };
  return { base: '#f2b640', L: '#fff6c0' };
}
function fxPop(cell, r, c, delay) { FX.pops.push({ cell, x: cellX(r, c), yl: cellYL(r), delay }); }
function fxFall(cell, r, c) {
  const x = cellX(r, c), y = G.ceilVis + G.shift + cellYL(r);
  cell.e.remove(); if (cell.iceE) cell.iceE.remove();
  const e = el('use', { href: bubHref(cell), transform: 'translate(' + f1(x) + ' ' + f1(y) + ')' }, $('fxG'));
  FX.items.push({ kind: 'fall', e, x, y, vx: R2(-50, 50), vy: R2(-80, -10), t: 0, sw: R2(0.26, 0.5), c: cell.t === 'n' ? cell.c : Math.floor(Math.random() * G.nc), ice: cell.ice, delay: 0 });
}
function fxSink(cell, r, c, delay) {
  const x = cellX(r, c), y = G.ceilVis + G.shift + cellYL(r);
  cell.e.remove(); if (cell.iceE) cell.iceE.remove();
  const e = el('use', { href: bubHref(cell), transform: 'translate(' + f1(x) + ' ' + f1(y) + ')', opacity: 0.85 }, $('fxG'));
  FX.items.push({ kind: 'sink', e, x, y, vx: R2(-20, 20), vy: 0, t: 0, delay, rot: R2(-90, 90) });
}
function spawnFish(x, y, c, delay) {
  const e = el('use', { href: '#fish' + c, transform: 'translate(' + f1(x) + ' ' + f1(y) + ') scale(0)' }, $('fxG'));
  const dir = Math.random() < 0.5 ? -1 : 1;
  FX.items.push({ kind: 'fish', e, x, y, dir, vx: dir * R2(140, 240), vy: R2(-60, 20), t: 0, s: R2(1.2, 1.6), delay });
}
function fxShards(x, y) {
  for (let i = 0; i < 7; i++) {
    const a = (i / 7) * TAU + Math.random() * 0.5, v = R2(80, 170);
    const e = el('path', { d: 'M0 -5L3 3L-3 2Z', fill: '#f2fbff', stroke: '#9fd4ec', 'stroke-width': 0.8 }, $('fxG'));
    FX.items.push({ kind: 'shard', e, x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v - 60, t: 0, rot: R2(0, 360), delay: 0 });
  }
}
function fxBomb(x, y) {
  spawnRing(x, y, '#ffcf6a', 16, 92, 0.45); spawnRing(x, y, '#ffffff', 10, 60, 0.3);
  spawnDrops(x, y, '#ffb347', 14, 300); spawnDrops(x, y, '#48566f', 10, 220); spawnDrops(x, y, '#fff3c4', 8, 260);
  const e = el('circle', { cx: f1(x), cy: f1(y), r: 64, fill: '#fff4d0', opacity: 0.8 }, $('fxG'));
  FX.temp.push({ e, t: 0, life: 0.25, kind: 'flash' });
}
function fxZap(y) {
  let d = 'M' + (FL - 6) + ' ' + f1(y);
  for (let x = FL + 20; x <= FR + 10; x += 24) d += 'L' + x + ' ' + f1(y + (Math.random() - 0.5) * 22);
  const g = el('g', {}, $('fxG'));
  el('path', { d, fill: 'none', stroke: '#fff3a0', 'stroke-width': 12, opacity: 0.35, 'stroke-linejoin': 'round' }, g);
  el('path', { d, fill: 'none', stroke: '#ffffff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' }, g);
  FX.temp.push({ e: g, t: 0, life: 0.4, kind: 'zap' });
  for (let x = FL + 30; x < FR; x += 70) spawnDrops(x, y, '#fff6b8', 2, 140);
}
function fxSparkle(x, y) { for (let i = 0; i < 6; i++) spawnDrops(x, y, COLORS[i].base, 3, 220); spawnRing(x, y, '#ffffff', 12, 56, 0.4); }
function updateFx(dt) {
  for (const d of FX.drops) {
    if (!d.live) continue;
    d.t += dt; if (d.t >= d.life) { d.live = false; d.e.classList.add('hidden'); continue; }
    d.vy += 260 * dt; d.vx *= 1 - 2.4 * dt; d.vy *= 1 - 1.2 * dt; d.x += d.vx * dt; d.y += d.vy * dt;
    const k = d.t / d.life;
    setA(d.e, { cx: f1(d.x), cy: f1(d.y), r: f1(d.r * (1 - 0.5 * k)), opacity: f1((1 - k) * 10) / 10 });
  }
  for (const g of FX.rings) {
    if (!g.live) continue;
    g.t += dt; if (g.t >= g.life) { g.live = false; g.e.classList.add('hidden'); continue; }
    const k = g.t / g.life; setA(g.e, { r: f1(lerp(g.r0, g.r1, ease(k))), opacity: f1((1 - k) * 10) / 10 });
  }
  for (const p of FX.texts) {
    if (!p.live) continue;
    p.t += dt; if (p.t >= p.life) { p.live = false; p.e.classList.add('hidden'); continue; }
    const k = p.t / p.life; setA(p.e, { y: f1(p.y - 46 * ease(k)), opacity: f1(Math.min(1, (1 - k) * 3) * 10) / 10 });
  }
  for (let i = FX.pops.length - 1; i >= 0; i--) {
    const p = FX.pops[i]; p.delay -= dt; if (p.delay > 0) continue;
    p.cell.e.remove(); if (p.cell.iceE) p.cell.iceE.remove();
    const y = p.yl + G.ceilVis + G.shift, col = colorOf(p.cell);
    spawnDrops(p.x, y, col.base, 6, 170); spawnDrops(p.x, y, col.L || '#ffffff', 4, 120); spawnRing(p.x, y, col.L || '#ffffff', 12, 30, 0.32);
    FX.pops.splice(i, 1);
  }
  for (let i = FX.items.length - 1; i >= 0; i--) {
    const it = FX.items[i];
    if (it.delay > 0) { it.delay -= dt; continue; }
    it.t += dt;
    if (it.kind === 'fall') {
      it.vy += 1300 * dt; it.x += it.vx * dt; it.y += it.vy * dt;
      it.e.setAttribute('transform', 'translate(' + f1(it.x) + ' ' + f1(it.y) + ')');
      if (it.t > it.sw) {
        it.kind = 'fish'; it.e.setAttribute('href', '#fish' + it.c); it.t = 0;
        it.dir = it.x < 640 ? -1 : 1; if (Math.random() < 0.3) it.dir = -it.dir;
        it.vx = it.dir * R2(150, 260); it.vy = R2(-110, -30); it.s = R2(1.25, 1.55);
        spawnDrops(it.x, it.y, COLORS[it.c].L, 6, 130); spawnRing(it.x, it.y, '#ffffff', 10, 26, 0.3);
        if (it.ice) fxShards(it.x, it.y);
      }
    } else if (it.kind === 'fish') {
      it.x += it.vx * dt; it.y += it.vy * dt; it.vy *= 1 - dt * 0.9;
      const grow = Math.min(1, it.t * 6), s = f1(it.s * grow * 100) / 100;
      it.e.setAttribute('transform', 'translate(' + f1(it.x) + ' ' + f1(it.y + Math.sin(it.t * 5) * 3) + ') scale(' + f1(it.dir * s * 100) / 100 + ' ' + s + ') rotate(' + f1(Math.sin(it.t * 14) * 9) + ')');
      if (it.x < -40 || it.x > W + 40 || it.t > 7) { it.e.remove(); FX.items.splice(i, 1); }
    } else if (it.kind === 'sink') {
      it.vy += 220 * dt; it.x += it.vx * dt; it.y += it.vy * dt;
      it.e.setAttribute('transform', 'translate(' + f1(it.x) + ' ' + f1(it.y) + ') rotate(' + f1(it.rot * it.t) + ')');
      it.e.setAttribute('opacity', f1(Math.max(0, 0.85 - it.t * 0.5) * 100) / 100);
      if (it.t > 1.8 || it.y > H + 30) { it.e.remove(); FX.items.splice(i, 1); }
    } else if (it.kind === 'shard') {
      it.vy += 420 * dt; it.x += it.vx * dt; it.y += it.vy * dt;
      it.e.setAttribute('transform', 'translate(' + f1(it.x) + ' ' + f1(it.y) + ') rotate(' + f1(it.rot + it.t * 400) + ')');
      it.e.setAttribute('opacity', f1(Math.max(0, 1 - it.t * 1.6) * 100) / 100);
      if (it.t > 0.65) { it.e.remove(); FX.items.splice(i, 1); }
    }
  }
  for (let i = FX.temp.length - 1; i >= 0; i--) {
    const t = FX.temp[i]; t.t += dt; const k = t.t / t.life;
    if (k >= 1) { t.e.remove(); FX.temp.splice(i, 1); continue; }
    t.e.setAttribute('opacity', f1((1 - k) * (t.kind === 'flash' ? 0.8 : 1) * 100) / 100);
  }
  for (let i = FX.tweens.length - 1; i >= 0; i--) {
