  }
}

/* ============ HUD ============ */
const HUD = {};
function buildHUD() {
  const g = $('hudG'), lab = { style: 'fill:#62808a' };
  panelShape(g, 26, 26, 318, 386);
  text(g, 50, 78, '\u6ce1\u6ce1\u6d77', 34, { 'font-weight': 900, style: 'fill:#24556a' });
  text(g, 164, 76, 'BUBBLE REEF', 15, { class: 'en', style: 'fill:#3f7688', 'letter-spacing': 2 });
  divider(g, 48, 96, 272);
  text(g, 48, 128, '\u5206\u6570', 15, lab);
  HUD.score = text(g, 46, 174, '0', 44, { class: 'num', 'font-weight': 800, style: 'fill:#20404c' });
  text(g, 224, 128, '\u6700\u9ad8', 15, lab);
  HUD.best = text(g, 224, 166, '0', 22, { class: 'num', 'font-weight': 700, style: 'fill:#3c5c66' });
  divider(g, 48, 194, 272);
  text(g, 48, 224, '\u5173\u5361', 15, lab);
  HUD.level = text(g, 48, 258, '', 22, { 'font-weight': 700 });
  text(g, 48, 294, '\u8ddd\u79bb\u4e0b\u964d', 15, lab);
  HUD.drop = text(g, 48, 330, '', 24, { 'font-weight': 700 });
  HUD.pips = el('g', {}, g);
  divider(g, 48, 352, 272);
  HUD.diff = text(g, 48, 388, '', 16, { style: 'fill:#3c5c66' });
  panelShape(g, 936, 26, 318, 386);
