function buildPips() {
  for (const grp of [HUD.pips, CRAB.pipG]) { while (grp.firstChild) grp.removeChild(grp.firstChild); }
  HUD.pipE = []; CRAB.pipE = [];
  for (let i = 0; i < G.dropEvery; i++) {
    HUD.pipE.push(el('circle', { cx: 176 + i * 17, cy: 322, r: 6, 'stroke-width': 1.6 }, HUD.pips));
    CRAB.pipE.push(el('circle', { cx: 718 + i * 15, cy: 690, r: 5.2, 'stroke-width': 1.5 }, CRAB.pipG));
  }
}
function updateHUD() {
  const d = DIFFS[G.diff];
  HUD.best.textContent = fmt(Math.max(G.score, G.mode === 'adv' ? SAVE.lvBest[G.diff][G.lv] : SAVE.endBest[G.diff]));
  HUD.level.textContent = G.mode === 'adv' ? '\u7b2c ' + (G.lv + 1) + ' \u5173 \u00b7 ' + LEVELS[G.lv].name : '\u65e0\u5c3d \u00b7 \u5df2\u63a8\u8fdb ' + G.rowsPushed + ' \u884c';
  const n = G.dropIn;
  HUD.drop.textContent = n <= 1 ? '\u4e0b\u4e00\u53d1\u5c31\u4e0b\u964d\uff01' : '\u8fd8\u6709 ' + n + ' \u6b65';
  HUD.drop.style.fill = n <= 1 ? '#c8404f' : '#2b3f47';
  show(HUD.pips, n > 1);
  const lit = (arr) => arr.forEach((p, i) => setA(p, { fill: i < n ? (n <= 2 ? '#e0606a' : '#3aa6a0') : 'none', stroke: n <= 2 ? '#b8404f' : '#2d7c78', opacity: i < n ? 1 : 0.45 }));
  lit(HUD.pipE); lit(CRAB.pipE);
  CRAB.pipLbl.textContent = '\u4e0b\u964d\u5012\u8ba1\u65f6 ' + n;
  HUD.diff.textContent = '\u96be\u5ea6\uff1a' + d.name + ' \u00b7 ' + d.colors + ' \u79cd\u989c\u8272 \u00b7 ' + (G.mode === 'adv' ? '\u5192\u9669' : '\u65e0\u5c3d');
  if (G.mode === 'adv') {
    HUD.goalT.textContent = '\u76ee\u6807'; HUD.goal.textContent = '\u6e05\u7a7a\u5168\u90e8\u6ce1\u6ce1';
    HUD.shotsT.textContent = '\u5df2\u53d1\u5c04'; HUD.shots.textContent = G.shots + ' \u53d1';
    const s = G.shots <= G.par ? 3 : G.shots <= Math.round(G.par * 1.4) ? 2 : 1;
    HUD.stars.forEach((e, i) => { setA(e, { fill: i < s ? '#f4c64a' : '#e4ddcc', stroke: i < s ? '#b98a2a' : '#b5ab94' }); show(e, true); });
    HUD.starInfo.textContent = '\u4e09\u661f \u2264 ' + G.par + ' \u53d1\u3000\u4e24\u661f \u2264 ' + Math.round(G.par * 1.4) + ' \u53d1';
  } else {
    HUD.goalT.textContent = '\u4e0b\u6b21\u52a0\u901f';
    const nextSpeed = G.dropEvery > d.endMin ? fmt((Math.floor(G.score / 4000) + 1) * 4000) + ' \u5206' : '\u5df2\u8fbe\u6700\u5feb';
    HUD.goal.textContent = nextSpeed;
    HUD.shotsT.textContent = '\u6d88\u9664'; HUD.shots.textContent = G.popped + ' \u4e2a \u00b7 \u5c0f\u9c7c ' + G.dropped;
    HUD.stars.forEach((e) => show(e, false));
    HUD.starInfo.textContent = '\u6bcf ' + G.dropEvery + ' \u53d1\u63a8\u8fdb\u4e00\u884c\u65b0\u6ce1\u6ce1';
  }
  HUD.combo.textContent = G.combo >= 2 ? '\u8fde\u51fb \u00d7' + G.combo + '\uff01' : G.maxCombo >= 2 ? '\u6700\u5927\u8fde\u51fb \u00d7' + G.maxCombo : '';
  HUD.combo.style.fill = G.combo >= 2 ? '#d9663a' : '#7a8f95';
}
function updateMuteIcon() { show(HUD.muteWave, !SAVE.mute); show(HUD.muteX, SAVE.mute); if (SCR.sndBtn) SCR.sndBtn.txt.textContent = SAVE.mute ? '\u97f3\u6548\uff1a\u5173' : '\u97f3\u6548\uff1a\u5f00'; }
/* ============ screens: title / level select / help / pause / result ============ */
