  SCR.bestTxt.textContent = '\u6700\u9ad8\u5206\uff08' + DIFFS[MENU.diff].name + '\uff09\u3000\u5192\u9669 ' + fmt(advBest(MENU.diff)) + '\u3000\u00b7\u3000\u65e0\u5c3d ' + fmt(SAVE.endBest[MENU.diff]);
