    const s = SAVE.stars[d][i]; total += s;
    b.stars.forEach((e, k) => setA(e, { fill: k < s ? '#f4c64a' : '#e2dccb', stroke: k < s ? '#b98a2a' : '#b9af98' }));
  });
  SCR.lvSub.textContent = '\u5192\u9669\u6a21\u5f0f \u00b7 ' + DIFFS[d].name + ' \u00b7 \u5df2\u89e3\u9501 ' + SAVE.unlock[d] + ' / 12 \u00b7 \u661f\u661f ' + total + ' / 36';
